import os, time, json
from bioblend.galaxy import GalaxyInstance
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
url=os.environ['GALAXY_URL'].rstrip('/')
gi=GalaxyInstance(url=url,key=key)
hid='bbd44e69cb8906b57a8f95fe12e5ad29'
samples=['KL1.tab','KL2.tab','KL3.tab','WL1.tab','WL2.tab','WL3.tab']
