    contents=gi.histories.show_history(hid, contents=True)
    states={c.get('name'):c.get('state') for c in contents if c.get('name') in samples}
    if all(v=='ok' for v in states.values()):
        for c in contents:
            if c.get('name') in samples:
                ids[c.get('name').replace('.tab','')]=c.get('id')
                print(c.get('hid'), c.get('id'), c.get('name'), c.get('state'), c.get('extension'), c.get('file_size'))
        open('/workspace/sample_ids.json','w').write(json.dumps(ids))
        print('all ok')
        break
    if i%5==0:
        print(i, states)
    time.sleep(3)
else:
    print('timeout', states)
